UPDATE lessons SET title='Year 7, Lesson 11: Digital basics and data', data=json_patch(data,'{"child_mission":"Personal data such as an address, a password, or a school photo tied to a daily routine should not be posted.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same technology/design idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nJudge these three posts: one that includes a password, one that says \"I like drawing maps of made-up cities\", and one with a uniform photo, River High and Creek Lane at 3:40. Which posts should stay offline?\n\nFEEDBACK\nThe password post and the uniform photo with River High and the 3:40 Creek Lane walk should not be shared. The drawing sentence is safe to share because it has no address, no school, no daily route and no password. A friends-only setting is still the wrong place for a password or a home address, because friends can forward a post.\n\nWATCH FOR\nA common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nOn paper, write one unsafe post and one safer hobby post using a made-up street, not your real address or password. Explain which details you removed and why.\n\nWrite a short reflection naming one observation, criterion or step you corrected and why.","interactive_activities":null,"learning_area":"Information and Software Technology","learning_intention":"Personal data such as an address, a password, or a school photo tied to a daily routine should not be posted.","lesson_number":11,"lesson_role":"Learn","materials":["Paper or typed answer space","Pencil","Optional: safe classroom tools/materials under teacher supervision","Device only when the lesson requires digital work"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["CT5-SAF-01"],"parent_notes":"Parent: Marking guidance for the independent task: On paper, write one unsafe post and one safer hobby post using a made-up street, not your real address or password. Explain which details you removed and why. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using privacy on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route.. Correction: The password post and the uniform photo with River High and the 3:40 Creek Lane walk should not be shared.. Why it helps the audience is stated.\n\nParent: Likely misconception: A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating privacy on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with privacy, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about privacy with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for privacy. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":2,"explanation":"This matches the taught method for privacy. The other choices miss a key step or use a common mistake.","options":["Ignore the observation or criteria and invent a more exciting result","Copy the model objects and call that independent work","The password post and the uniform photo with River High and the 3:40 Creek Lane walk should not be shared","A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route"],"question":"Judge these three posts: one that includes a password, one that says \"I like drawing maps of made-up cities\", and one with a uniform photo, River High and Creek Lane at 3:40. Which posts should stay offline?","type":"multiple_choice"},{"correct_index":0,"explanation":"This is the misconception to avoid for privacy; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route","Personal data such as an address, a password, or a school photo tied to a daily routine should not be posted","The password post and the uniform photo with River High and the 3:40 Creek Lane walk should not be shared","Careful use of address with clear evidence"],"question":"Which statement is a common mistake when working with privacy?","type":"multiple_choice"},{"correct_index":3,"explanation":"Understanding is shown by new evidence and a named address, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Repeat the worked example wording with no new evidence","A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route","Name address only, without linking it to privacy","Apply privacy to new material and name the address used"],"question":"Which response best applies privacy with new evidence?","type":"multiple_choice"},{"correct_index":1,"explanation":"The stronger choice uses design criteria, safe making steps or test evidence appropriately for this lesson on privacy. The other choices miss a key step or use a common mistake.","options":["A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route","The password post and the uniform photo with River High and the 3:40 Creek Lane walk should not be shared","Start making with no criteria or safety check","Call the first attempt finished without testing"],"question":"Which response best evaluates design criteria, safe making steps or test evidence when analysing privacy?","type":"multiple_choice"},{"correct_index":0,"explanation":"Strong answers name specific evidence and what it shows. The other choices miss a key step or use a common mistake.","options":["Name a criterion, safety step or test result and say how it improves privacy","Start making with no criteria or safety check","Call the first attempt finished without testing","A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route"],"question":"Which evidence move best supports a claim about privacy?","type":"multiple_choice"},{"correct_index":3,"explanation":"The stronger choice matches the taught idea (Personal data such as an address, a password, or a school photo tied to) with concrete detail. The other choices miss a key step or use a common mistake.","options":["A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route","Start making with no criteria or safety check","Call the first attempt finished without testing","Mina''s unsafe post gives 14 Banks Street, River High, a uniform photo and a walk along Creek Lane at 3:40 each day"],"question":"Which choice best applies this lesson idea about privacy?","type":"multiple_choice"},{"correct_index":3,"explanation":"Accuracy means checking evidence and honouring limits or protocols. The other choices miss a key step or use a common mistake.","options":["Invent missing details to make the answer sound complete","Ignore safety or cultural protocols to finish faster","Treat every claim as equally reliable without checking a source or cue","Check criteria and safety, record a test result, and note one honest improvement"],"question":"Which action keeps design criteria, safe making steps or test evidence accurate for privacy?","type":"multiple_choice"},{"correct_index":0,"explanation":"Independence requires a new example that still uses the taught skill. The other choices miss a key step or use a common mistake.","options":["On paper, write one unsafe post and one safer hobby post using a made-up street, not your real address or password","Retype the worked example with no new example","A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route","Name address only, with no linked example"],"question":"Which independent response best applies privacy to new material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about privacy with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating privacy on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using privacy on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for privacy. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with privacy, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route.. Correction: The password post and the uniform photo with River High and the 3:40 Creek Lane walk should not be shared.. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s5-information-software-technology-y9-w06-l1","sort_activity":null,"source_note":"Catalogue learning area is Information and Software Technology. Proposed Year 7 alignment uses Computing Technology 7–10 (2022). Stage 4 may adjust Stage 5 outcomes (CT4-ADJ-01). Content-point mapping pending. Not NESA verified. No live network attacks or external logins are required.","spelling":null,"spelling_focus":null,"stage":"S4","stage_hints":{"accept":["Today you will practise privacy.","Read the mission before you start observing, designing or testing.","Keep the property, criterion or variable you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the observation, criterion or step that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore observations, criteria or fair tests.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread labels, measurements and sequence of steps.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact observation, criterion or test step before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key observations or criteria.","Say what each observation or criterion shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or method, not only how neat the drawing looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh object or context that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new objects or data."]},"subject":"Information and Software Technology","success_criteria":["I can use privacy with a specific example from this lesson.","I can identify address and explain why it matters.","I can practise routine independently on a new prompt.","I can notice password needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":1,"explanation":"Personal data such as an address, a password, or a school photo tied to a daily routine should not be posted. Supported records follow the actual observations, criteria and purpose of the task. The other choices miss a key step or use a common mistake.","options":["A guess with no evidence","Personal data such as an address, a password, or a school photo tied to a daily routine should not be posted","A claim unrelated to the observation, test or criteria","An answer copied without understanding"],"question":"Which choice best shows accurate use of this idea about privacy?","type":"multiple_choice"},"example":"WORKED MODEL\nMina''s unsafe post gives 14 Banks Street, River High, a uniform photo and a walk along Creek Lane at 3:40 each day. Together those details tell strangers where she lives, where she studies and when she is on that route. A safer post says \"I enjoyed the science fair\" and leaves out the address, the school, the route and the password. She asks a classmate before posting a photo of that person, and she uses made-up examples in class rather than her real address.\n\nTRY FIRST\nJudge these three posts: one that includes a password, one that says \"I like drawing maps of made-up cities\", and one with a uniform photo, River High and Creek Lane at 3:40. Which posts should stay offline?\n\nFEEDBACK\nThe password post and the uniform photo with River High and the 3:40 Creek Lane walk should not be shared. The drawing sentence is safe to share because it has no address, no school, no daily route and no password. A friends-only setting is still the wrong place for a password or a home address, because friends can forward a post.","explain":"Personal data such as an address, a password, or a school photo tied to a daily routine should not be posted.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen, measured or tested against criteria.\n\nHOW TO WORK\nRead the worked example and name the observations, properties, criteria or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer. For practical technology work, follow teacher safety rules for tools, food and devices.","icon":"📖","notice":"A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route. Correct the claim, criteria use or method, not just the neatness of the diagram.","title":"Understand and model","visual":[{"alt":"Do not post an address, a password, or a daily route. A safer post says I enjoyed the science fair.","caption":"Private details locate a person or open an account. A hobby sentence without those details is safer.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Do not post</text><text x=\"28\" y=\"78\">address, password, or route</text><text x=\"358\" y=\"42\">Safer post</text><text x=\"358\" y=\"78\">I enjoyed the science fair</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which observation or criterion matters most.","who":"pip"},{"text":"Name the observations, criteria or test steps that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Mina''s unsafe post gives 14 Banks Street, River High, a uniform photo and a walk along Creek Lane at 3:40 each day. Toge Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which observation or criterion matters most.\nJuno: Name the observations, criteria or test steps that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Mina''s unsafe post gives 14 Banks Street, River High, a uniform photo and a walk along Creek Lane at 3:40 each day. Toge Then write your own evidence."}}]},{"check":{"correct_index":3,"explanation":"Make the technology idea visible: name the observation, source or example you used and say why it supports the claim. Supported records follow the actual observations, criteria and purpose of the task. The other choices miss a key step or use a common mistake.","options":["A claim unrelated to the observation, test or criteria","An answer copied without understanding","A guess with no evidence","Make the technology idea visible: name the observation, source or example you used and say why it supports the claim"],"question":"Which choice best shows accurate use of this idea about privacy?","type":"multiple_choice"},"example":"WORKED MODEL\nMina''s unsafe post gives 14 Banks Street, River High, a uniform photo and a walk along Creek Lane at 3:40 each day. Together those details tell strangers where she lives, where she studies and when she is on that route. A safer post says \"I enjoyed the science fair\" and leaves out the address, the school, the route and the password. She asks a classmate before posting a photo of that person, and she uses made-up examples in class rather than her real address. Look at each observation, source detail or example that carries the idea.\n\nTRY FIRST\nList the key observations, sources or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the technology idea visible: name the observation, source or example you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen, measured or tested against criteria.\n\nHOW TO WORK\nRead the worked example and name the observations, properties, criteria or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer. For practical technology work, follow teacher safety rules for tools, food and devices.","icon":"📖","notice":"Writing only a final label without evidence does not show technology thinking. Correct the claim, criteria use or method, not just the neatness of the diagram.","title":"Show the evidence","visual":[{"alt":"School name plus a photo plus a 3:40 walk is a routine to keep private. Ask before posting someone else.","caption":"One harmless detail can become unsafe when it is combined with a place and a regular time.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Risky combination</text><text x=\"28\" y=\"78\">school, photo and 3:40 walk</text><text x=\"358\" y=\"42\">Before posting</text><text x=\"358\" y=\"78\">ask the other person first</text></g></svg>"}]},{"check":{"correct_index":3,"explanation":"Use an intentionally incorrect claim as a comparison. Name its specific technology error, then show the corrected evidence-based claim. Supported records follow the actual observations, criteria and purpose of the task. The other choices miss a key step or use a common mistake.","options":["A claim unrelated to the observation, test or criteria","An answer copied without understanding","A guess with no evidence","Use an intentionally incorrect claim as a comparison"],"question":"Which choice best shows accurate use of this idea about privacy?","type":"multiple_choice"},"example":"WORKED MODEL\nA common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route. Here is a more productive model: Mina''s unsafe post gives 14 Banks Street, River High, a uniform photo and a walk along Creek Lane at 3:40 each day. Together those details tell strangers where she lives, where she studies and when she is on that route. A safer post says \"I enjoyed the science fair\" and leaves out the address, the school, the route and the password. She asks a classmate before posting a photo of that person, and she uses made-up examples in class rather than her real address.\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\nThe password post and the uniform photo with River High and the 3:40 Creek Lane walk should not be shared. The drawing sentence is safe to share because it has no address, no school, no daily route and no password. A friends-only setting is still the wrong place for a password or a home address, because friends can forward a post.","explain":"Use an intentionally incorrect claim as a comparison. Name its specific technology error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen, measured or tested against criteria.\n\nHOW TO WORK\nRead the worked example and name the observations, properties, criteria or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer. For practical technology work, follow teacher safety rules for tools, food and devices.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. A common mistake is to think a friends-only post is a safe place for a home address, a password or a daily route. Correct the claim, criteria use or method, not just the neatness of the diagram.","title":"Test a misconception"},{"check":{"correct_index":0,"explanation":"Use the same technology idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence. Supported records follow the actual observations, criteria and purpose of the task. The other choices miss a key step or use a common mistake.","options":["Use the same technology idea on a new place, person, source or context, not a copy of the worked example","A claim unrelated to the observation, test or criteria","An answer copied without understanding","A guess with no evidence"],"question":"Which choice best shows accurate use of this idea about privacy?","type":"multiple_choice"},"example":"WORKED MODEL\nPersonal data such as an address, a password, or a school photo tied to a daily routine should not be posted. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInquire into or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same technology idea as the model, but contain different evidence.","explain":"Use the same technology idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen, measured or tested against criteria.\n\nHOW TO WORK\nRead the worked example and name the observations, properties, criteria or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer. For practical technology work, follow teacher safety rules for tools, food and devices.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim, criteria use or method, not just the neatness of the diagram.","title":"Transfer to a new investigation"}],"title":"Year 7, Lesson 11: Digital basics and data","unit_number":1,"unit_title":"Digital basics and data","week":9,"week_in_unit":6,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nMina''s unsafe post gives 14 Banks Street, River High, a uniform photo and a walk along Creek Lane at 3:40 each day. Together those details tell strangers where she lives, where she studies and when she is on that route. A safer post says \"I enjoyed the science fair\" and leaves out the address, the school, the route and the password. She asks a classmate before posting a photo of that person, and she uses made-up examples in class rather than her real address.\n\nWrite what makes this example accurate, naming the observations, criteria, properties or test steps used.","worked_visuals":[{"alt":"Do not post an address, a password, or a daily route. A safer post says I enjoyed the science fair.","caption":"Private details locate a person or open an account. A hobby sentence without those details is safer.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Do not post</text><text x=\"28\" y=\"78\">address, password, or route</text><text x=\"358\" y=\"42\">Safer post</text><text x=\"358\" y=\"78\">I enjoyed the science fair</text></g></svg>"},{"alt":"School name plus a photo plus a 3:40 walk is a routine to keep private. Ask before posting someone else.","caption":"One harmless detail can become unsafe when it is combined with a place and a regular time.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Risky combination</text><text x=\"28\" y=\"78\">school, photo and 3:40 walk</text><text x=\"358\" y=\"42\">Before posting</text><text x=\"358\" y=\"78\">ask the other person first</text></g></svg>"}],"year_level":"Year 7"}') WHERE seed_key='s5-information-software-technology-y9-w06-l1' AND family_id IS NULL;
